const pool = require('../pool');

// Records one committed half-move. Only committed moves ever reach here — a
// move that fails validation never touches the database — so this table is the
// game's true move list rather than a log of attempts.
async function insert({ gameId, ply, uci }) {
    // id is SERIAL and generated by Postgres, unlike games.id which is a UUID
    // minted in Node. A move id never leaves the server, so there is nothing to
    // know before the insert and nothing to keep unguessable.
    const result = await pool.query(
        `INSERT INTO moves (game_id, ply, uci)
         VALUES ($1, $2, $3)
         RETURNING id, game_id, ply, uci, created_at`,
        [gameId, ply, uci]
    );
    return result.rows[0];
}

module.exports = { insert };